301				WHERE organization_id = ${identity.organizationId}
302					AND client_id = ${identity.clientId}
303					AND user_id = ${identity.userId}
304					AND conversation_key = ${identity.conversationKey}
305					AND tool_call_key = ${identity.toolCallKey}
306					AND expires_at > now()
307			`;
308		}
