vi.mock("@modelcontextprotocol/ext-apps", () => ({
  App: class { addEventListener(n:string,h:(p:unknown)=>void){const s=bridge.listeners.get(n)??new Set();s.add(h);bridge.listeners.set(n,s)} removeEventListener(){} callServerTool=bridge.callServerTool; connect=bridge.connect; getHostContext(){return {theme:"light"}} async openLink(){return {isError:false}} },
  PostMessageTransport: class { async close(){} },
}));
const originalParent=Object.getOwnPropertyDescriptor(window,"parent");
beforeEach(()=>{vi.resetModules();bridge.listeners.clear();bridge.connect.mockResolvedValue(undefined)});
afterEach(()=>{if(originalParent)Object.defineProperty(window,"parent",originalParent)});
it("preserves approval capability across metadata-free continuation", async()=>{
  Object.defineProperty(window,"parent",{configurable:true,value:Object.assign(new EventTarget(),{location:{origin:"https://portable-host.example"}})});
  bridge.callServerTool.mockImplementation(async({name}:{name:string})=>name==="restore_lobu_app_result"?{isError:false,structuredContent:{found:true,tool_name:"render_lobu_view",data:{version:1,actions:[{id:"review"}]},view_state:{}}}:{isError:false});
  const {Provider,useMcpApp}=await import("./host");
  function Probe(){const {data,callTool}=useMcpApp<{actions:Array<{id:string}>}>();return <><span>{data?.actions.map(a=>a.id).join(",")}</span><button onClick={()=>void callTool("resolve_lobu_approval",{decision:"approve"})}>Approve</button></>}
  render(<Provider devMock={{actions:[]}}><Probe/></Provider>); await waitFor(()=>expect(bridge.connect).toHaveBeenCalled());
  act(()=>{for(const h of bridge.listeners.get("toolresult")??[])h({structuredContent:{},_meta:{"lobu/mcp-app-snapshot-capability":"result-token","lobu/approval-capability":"approval-token"}})});
  expect(await screen.findByText("review")).toBeInTheDocument();
  act(()=>{for(const h of bridge.listeners.get("toolresult")??[])h({structuredContent:{version:1,actions:[{id:"approve",tool:"resolve_lobu_approval"},{id:"review"}]}})});
  expect(await screen.findByText("approve,review")).toBeInTheDocument(); bridge.callServerTool.mockClear(); fireEvent.click(screen.getByRole("button",{name:"Approve"}));
  await waitFor(()=>expect(bridge.callServerTool).toHaveBeenCalledWith({name:"resolve_lobu_approval",arguments:{decision:"approve"},_meta:{"lobu/approval-capability":"approval-token"}}));
});
